package com.wiktor.jogger;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.Color;
import android.os.*;
import android.text.*;
import android.view.*;
import android.view.inputmethod.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;

public final class GameActivity extends Activity implements SurfaceHolder.Callback,TouchOverlay.Actions {
 private SurfaceView surface;private TouchOverlay touch;private EditText keyboard;private boolean started,editing,testing,probe,ending;private JSONObject plan,instance;private Core.Store store;private File gameDir;private TextView loading;private final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle state){super.onCreate(state);setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_FULLSCREEN);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);getWindow().getDecorView().setSystemUiVisibility(5894);store=new Core.Store(this);testing=getIntent().getBooleanExtra("controlsTest",false);probe=getIntent().getBooleanExtra("probe",false);
  try{if(!testing&&!probe){File f=new File(getNoBackupFilesDir(),"launch.json");plan=Core.read(f);f.delete();instance=store.instance(plan.getString("instance"));gameDir=store.dir(instance.getString("id"));}else{gameDir=new File(store.root,"engine-check");gameDir.mkdirs();instance=new JSONObject().put("resolution",70);}}catch(Exception e){error(e.toString());return;}
  FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff202020);surface=new SurfaceView(this);root.addView(surface,new FrameLayout.LayoutParams(-1,-1));touch=new TouchOverlay(this,gameDir,this,testing);root.addView(touch,new FrameLayout.LayoutParams(-1,-1));keyboard=new EditText(this);keyboard.setSingleLine(true);keyboard.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);keyboard.setImeOptions(EditorInfo.IME_FLAG_NO_EXTRACT_UI|EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING|EditorInfo.IME_ACTION_SEND);keyboard.setAlpha(0);keyboard.setFocusableInTouchMode(true);root.addView(keyboard,new FrameLayout.LayoutParams(1,1,Gravity.BOTTOM));keyboard.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(editing||testing)return;for(int i=0;i<before;i++)Native.press(259);String str=s.subSequence(start,start+count).toString();str.codePoints().forEach(cp->{if(cp>=32)Native.input(3,cp,0,0,0);});}public void afterTextChanged(Editable e){}});keyboard.setOnEditorActionListener((v,a,event)->{if(!testing)Native.press(257);leaveChat();return true;});loading=new TextView(this);loading.setTextColor(Color.WHITE);loading.setGravity(Gravity.CENTER);loading.setTextSize(16);loading.setText(testing?"":"Starting independent Jogger engine...");root.addView(loading,new FrameLayout.LayoutParams(-1,80,Gravity.CENTER));setContentView(root);if(!testing)surface.getHolder().addCallback(this);
  if(Build.VERSION.SDK_INT>=24)try{getWindow().setSustainedPerformanceMode(true);}catch(Exception ignored){}
 }
 private void error(String message){new AlertDialog.Builder(this).setTitle("Jogger engine report").setMessage(message).setPositiveButton("Return to launcher",(d,w)->{finish();android.os.Process.killProcess(android.os.Process.myPid());}).setNeutralButton("View log",(d,w)->showLog()).setCancelable(false).show();}
 private void showLog(){try{File f=new File(gameDir,"latest-jogger.log");String s=f.exists()?Core.text(f):"No game log was written";TextView v=new TextView(this);v.setText(s.substring(Math.max(0,s.length()-24000)));v.setTextIsSelectable(true);v.setTextSize(12);ScrollView scroll=new ScrollView(this);scroll.addView(v);new AlertDialog.Builder(this).setTitle("Engine log").setView(scroll).setPositiveButton("Close",(d,w)->error("Engine stopped")).show();}catch(Exception e){error(e.toString());}}
 @Override public void surfaceCreated(SurfaceHolder h){}
 @Override public void surfaceChanged(SurfaceHolder holder,int format,int width,int height){if(testing)return;int ratio=instance.optInt("resolution",70);int rw=Math.max(320,(surface.getWidth()*ratio/100)&~1),rh=Math.max(240,(surface.getHeight()*ratio/100)&~1);if(width!=rw||height!=rh){holder.setFixedSize(rw,rh);return;}Native.surface(holder.getSurface(),rw,rh);if(Build.VERSION.SDK_INT>=30)try{holder.getSurface().setFrameRate(instance.optString("preset").equals("Battery")?30:60,0);}catch(Exception ignored){}if(started)return;started=true;new Thread(()->{try{if(probe)plan=probePlan();final JSONObject p=plan;main.post(()->loading.setVisibility(View.GONE));String result=Native.boot(p.getString("runtime"),getApplicationInfo().nativeLibraryDir,gameDir.toString(),p.getString("renderer"),strings(p.getJSONArray("jvm")),p.getString("main"),strings(p.getJSONArray("args")));main.post(()->error(result));}catch(Throwable e){main.post(()->error(e.toString()));}},"Jogger Minecraft JVM").start();}
 private JSONObject probePlan()throws Exception{Core.cancel.set(false);File runtime=Core.runtime(this,s->main.post(()->loading.setText(s)));File jar=new File(store.root,"jogger-agent.jar");try(InputStream i=getAssets().open("jogger-agent.jar");FileOutputStream o=new FileOutputStream(jar)){Core.copy(i,o,16*1024*1024);}List<String>cp=new ArrayList<>();cp.add(jar.toString());File libs=new File(store.root,"probe-libs");libs.mkdirs();for(String n:getAssets().list("probe-libs")){File f=new File(libs,n);try(InputStream i=getAssets().open("probe-libs/"+n);FileOutputStream o=new FileOutputStream(f)){Core.copy(i,o,16*1024*1024);}cp.add(f.toString());}String nd=getApplicationInfo().nativeLibraryDir,renderer=nd+"/"+new JSONObject(Core.assetText(this,"engine.json")).getString("renderer");List<String>args=Arrays.asList("-Xmx384m","-Djava.home="+runtime,"-Djava.library.path="+nd,"-Dorg.lwjgl.librarypath="+nd,"-Dorg.lwjgl.system.allocator=system","-Dorg.lwjgl.glfw.libname="+nd+"/libglfw_jogger.so","-Dorg.lwjgl.opengl.libname="+renderer,"-Djava.class.path="+String.join(File.pathSeparator,cp));return new JSONObject().put("runtime",runtime.toString()).put("renderer",renderer).put("jvm",new JSONArray(args)).put("main","com.wiktor.jogger.agent.EngineProbe").put("args",new JSONArray());}
 private static String[]strings(JSONArray a)throws Exception{String[]r=new String[a.length()];for(int i=0;i<r.length;i++)r[i]=a.getString(i);return r;}
 @Override public void surfaceDestroyed(SurfaceHolder h){if(!testing){touch.reset();Native.surface(null,0,0);}}
 @Override public void type(){editing=true;keyboard.setText("");editing=false;keyboard.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(keyboard,InputMethodManager.SHOW_IMPLICIT);}
 @Override public void leaveChat(){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(keyboard.getWindowToken(),0);keyboard.clearFocus();}
 @Override public void exit(){if(testing){finish();return;}if(ending)return;new AlertDialog.Builder(this).setTitle("Save and leave Minecraft?").setMessage("This asks Minecraft to close normally so it can save the world.").setPositiveButton("Save and leave",(d,w)->{ending=true;touch.reset();Native.input(7,0,0,0,0);loading.setText("Waiting for Minecraft to save and close...");loading.setVisibility(View.VISIBLE);}).setNegativeButton("Cancel",null).show();}
 @Override public void onBackPressed(){if(testing)finish();else{Native.press(256);leaveChat();}}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(testing||keyboard.hasFocus())return super.dispatchKeyEvent(e);int k=0;switch(e.getKeyCode()){case KeyEvent.KEYCODE_BACK:k=256;break;case KeyEvent.KEYCODE_W:k=87;break;case KeyEvent.KEYCODE_A:k=65;break;case KeyEvent.KEYCODE_S:k=83;break;case KeyEvent.KEYCODE_D:k=68;break;case KeyEvent.KEYCODE_SPACE:k=32;break;case KeyEvent.KEYCODE_SHIFT_LEFT:k=340;break;case KeyEvent.KEYCODE_CTRL_LEFT:k=341;break;case KeyEvent.KEYCODE_E:k=69;break;case KeyEvent.KEYCODE_T:k=84;break;case KeyEvent.KEYCODE_ENTER:k=257;break;case KeyEvent.KEYCODE_DEL:k=259;break;}if(k!=0){Native.key(k,e.getAction()==KeyEvent.ACTION_DOWN);return true;}return super.dispatchKeyEvent(e);}
 @Override protected void onPause(){if(touch!=null)touch.reset();if(!testing&&started){if(Native.state()[0]==1)Native.press(256);Native.input(6,0,0,0,0);}super.onPause();}
 @Override protected void onResume(){super.onResume();if(!testing&&started)Native.input(6,1,0,0,0);}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(!focused&&touch!=null)touch.reset();if(focused)getWindow().getDecorView().setSystemUiVisibility(5894);}
}
